import { IsString, IsNotEmpty, IsOptional, IsUUID, IsBase64 } from 'class-validator';

export class CreateVaultDto {
  /**
   * Vault id, generated by the client. It has to exist before the request is
   * built because kekVerify is this id encrypted with the vault's KEK.
   */
  @IsUUID('4')
  id: string;

  @IsString()
  @IsNotEmpty()
  @IsBase64()
  kekSalt: string;

  @IsString()
  @IsNotEmpty()
  @IsBase64()
  kekVerify: string;

  @IsString()
  @IsNotEmpty()
  @IsBase64()
  kekVerifyNonce: string;

  @IsString()
  @IsOptional()
  @IsBase64()
  labelEncrypted?: string;

  @IsString()
  @IsOptional()
  @IsBase64()
  labelNonce?: string;
}
